(()=>{
  const N = 90;
  const rafOrig = window.requestAnimationFrame.bind(window);
  const stOrig  = window.setTimeout.bind(window);
  const acc = {}; let n = 0; const t0 = performance.now();
  const nombre = f => (f && f.name) ? f.name
      : ('anón: ' + String(f).replace(/\s+/g,' ').slice(0,70));
  const mide = (cb, tipo) => function(...a){
    const k = tipo + ' · ' + nombre(cb); const ini = performance.now();
    try { return cb.apply(this, a); }
    finally { const d = performance.now() - ini;
      (acc[k] || (acc[k] = {n:0, ms:0, max:0}));
      acc[k].n++; acc[k].ms += d; if(d > acc[k].max) acc[k].max = d; }
  };
  window.requestAnimationFrame = cb => rafOrig(mide(cb, 'rAF'));
  window.setTimeout = (cb, ms, ...r) =>
    (typeof cb === 'function') ? stOrig(mide(cb, 'timeout'), ms, ...r) : stOrig(cb, ms, ...r);

  const fin = () => {
    window.requestAnimationFrame = rafOrig; window.setTimeout = stOrig;
    const T = performance.now() - t0;
    console.table(Object.entries(acc).map(([k,v]) => ({
      callback: k, llamadas: v.n, 'ms total': +v.ms.toFixed(1),
      'ms/llamada': +(v.ms/v.n).toFixed(2), 'pico ms': +v.max.toFixed(1),
      '% del reloj': (100*v.ms/T).toFixed(1) + '%'
    })).sort((a,b) => b['ms total'] - a['ms total']));
    console.log('ventana', T.toFixed(0), 'ms ·', n, 'frames · fps', (1000/(T/n)).toFixed(1));
    console.log('%cRESTAURADO','color:#2a2');
  };
  const cuenta = () => { if(++n < N) return rafOrig(cuenta); fin(); };
  rafOrig(cuenta);
  console.log('cazando bucles durante', N, 'frames — no toques nada…');
})()
